<?php
namespace SerbenConnect\Services; use SerbenConnect\API\Client;
if(!defined('ABSPATH')){exit;} final class FaturasService{private $c;function __construct(?Client $c=null){$this->c=$c?:new Client();}function getPorId(int $id):array{return $this->c->integrationGet('faturas','Faturas/getInfosFaturaById',['id_fatura'=>$id]);}function creditoPorDocumento(string $d,int $page=1,int $limit=20):array{return $this->c->integrationGet('faturas','Faturas/getFaturasCreditoByDocumento',['documento'=>preg_replace('/\D+/','',$d),'page'=>max(1,$page),'limit'=>min(100,max(1,$limit))]);}function gerarPix(array $p):array{return $this->c->integrationPost('faturas','Faturas/gerarPixPorIdFatura',$p);}function gerarBolepix(array $p):array{return $this->c->integrationPost('faturas','Faturas/gerarBolepixPorIdFatura',$p);}function enviarEmail(array $p):array{return $this->c->integrationPost('faturas','Faturas/enviarEmailPorFatura',$p);}function cancelar(array $p):array{return $this->c->integrationPost('faturas','Faturas/cancelarFaturaPorId',$p);}}
